def add_months(d: date, n: int) -> date:
    """d の n ヶ月後。移動先に同じ日が無ければ末日に丸める。"""
    index = (d.month - 1) + n
    year = d.year + index // 12
    month = index % 12 + 1
    last_day = calendar.monthrange(year, month)[1]
    return date(year, month, min(d.day, last_day))

