        super().__init__(field, f"項目がありません: {field}")


class TypeMismatchError(ValidationError):
    """項目はあるが型が違う。"""

    def __init__(self, field: str, expected: type) -> None:
        super().__init__(field, f"{field} は {expected.__name__} で入力してください")
        self.expected = expected


def validate(record: dict) -> bool:
    expected_types = {"name": str, "age": int}
    for field, expected in expected_types.items():
        if field not in record:
            raise MissingFieldError(field)
        if not isinstance(record[field], expected):
            raise TypeMismatchError(field, expected)
    return True

